package exercise

import (
	"sort"
	"strings"
	"testing"
	"time"
)

func checkBoard(t *testing.T, n int, board []string) {
	t.Helper()
	if len(board) != n {
		t.Fatalf("board %v has %d rows, want %d", board, len(board), n)
	}
	cols := map[int]bool{}
	diags := map[int]bool{}
	antis := map[int]bool{}
	for r, row := range board {
		if len(row) != n {
			t.Fatalf("board %v: row %d has %d characters, want %d", board, r, len(row), n)
		}
		if strings.Count(row, "Q") != 1 || strings.Count(row, ".") != n-1 {
			t.Fatalf("board %v: row %d must hold one Q and otherwise only dots", board, r)
		}
		c := strings.Index(row, "Q")
		if cols[c] || diags[r+c] || antis[r-c] {
			t.Fatalf("board %v: the queen in row %d is attacked by a queen above it", board, r)
		}
		cols[c], diags[r+c], antis[r-c] = true, true, true
	}
}

func checkSolutions(t *testing.T, n int, got [][]string, wantCount int) {
	t.Helper()
	if len(got) != wantCount {
		t.Fatalf("SolveNQueens(%d) returned %d solutions, want %d", n, len(got), wantCount)
	}
	seen := map[string]bool{}
	for _, board := range got {
		checkBoard(t, n, board)
		key := strings.Join(board, "/")
		if seen[key] {
			t.Fatalf("SolveNQueens(%d) returned %v more than once", n, board)
		}
		seen[key] = true
	}
}

func TestSolveNQueensExactBoards(t *testing.T) {
	cases := []struct {
		n    int
		want []string
	}{
		{1, []string{"Q"}},
		{4, []string{"..Q./Q.../...Q/.Q..", ".Q../...Q/Q.../..Q."}},
	}
	for _, c := range cases {
		var got []string
		for _, board := range SolveNQueens(c.n) {
			got = append(got, strings.Join(board, "/"))
		}
		sort.Strings(got)
		sort.Strings(c.want)
		if strings.Join(got, " ") != strings.Join(c.want, " ") {
			t.Errorf("SolveNQueens(%d) = %v, want %v", c.n, got, c.want)
		}
	}
}

func TestSolveNQueensCounts(t *testing.T) {
	counts := map[int]int{1: 1, 2: 0, 3: 0, 4: 2, 5: 10, 6: 4, 7: 40, 8: 92, 9: 352}
	for n, want := range counts {
		checkSolutions(t, n, SolveNQueens(n), want)
	}
}

func TestSolveNQueensPrunes(t *testing.T) {
	const n, want = 12, 14200
	start := time.Now()
	got := SolveNQueens(n)
	elapsed := time.Since(start)
	checkSolutions(t, n, got, want)
	const budget = 5 * time.Second
	if elapsed > budget {
		t.Fatalf("took %v for n = %d, over the %v budget: abandon a partial board as soon as it has a conflict", elapsed, n, budget)
	}
}

