package exercise

import "strings"

func SolveNQueens(n int) [][]string {
	result := [][]string{}
	queens := make([]int, n)
	cols := make([]bool, n)
	diags := make([]bool, 2*n)
	antis := make([]bool, 2*n)

	var place func(row int)
	place = func(row int) {
		if row == n {
			board := make([]string, n)
			for r, c := range queens {
				board[r] = strings.Repeat(".", c) + "Q" + strings.Repeat(".", n-c-1)
			}
			result = append(result, board)
			return
		}
		for c := 0; c < n; c++ {
			d, a := row+c, row-c+n
			if cols[c] || diags[d] || antis[a] {
				continue
			}
			queens[row] = c
			cols[c], diags[d], antis[a] = true, true, true
			place(row + 1)
			cols[c], diags[d], antis[a] = false, false, false
		}
	}
	place(0)
	return result
}
